mapper.update:
update pilipili.user_message
set read_type = #{userMessage.readType}
where user_id = #{userMessageQuery.userId} and message_type = #{userMessageQuery.messageType}

mapper.select:
select um.*, u.user_name, u.avatar, vi.video_name, vi.video_cover
from pilipili.user_message um left join pilipili.user u on um.send_user_id = u.user_id left join pilipili.video_info vi on um.video_id = vi.video_id
where um.user_id = #{userMessageQuery.userId} and message_type = #{userMessageQuery.messageType}

mapper.delete:
delete
